import { useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { toast } from "sonner";
import {
  Briefcase,
  MapPin,
  Building2,
  Clock,
  DollarSign,
  Layers,
  ArrowLeft,
  Linkedin,
  Twitter,
  Link2,
  Calendar,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";

// ─── Types ───────────────────────────────────────────────────────────────────

interface CareerConfig {
  company_name: string;
  logo_url: string | null;
  brand_color: string;
  tagline: string | null;
  about: string | null;
}

interface JobDetail {
  id: string;
  title: string;
  job_description: string | null;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  salary_range: string | null;
  created_at: string;
  is_published: boolean;
}

interface RelatedJob {
  id: string;
  title: string;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  created_at: string;
}

// ─── Sub-components ──────────────────────────────────────────────────────────

function CareerHeader({
  config,
  slug,
}: {
  config: CareerConfig | null | undefined;
  slug: string | undefined;
}) {
  return (
    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
      <div className="max-w-5xl mx-auto px-4 py-4 flex items-center gap-3">
        {config?.logo_url ? (
          <img
            src={config.logo_url}
            alt={config.company_name}
            className="h-8 w-8 rounded object-cover"
          />
        ) : (
          <div className="h-8 w-8 rounded bg-primary/10 flex items-center justify-center">
            <Layers className="h-4 w-4 text-primary" />
          </div>
        )}
        <Link
          to={slug ? `/careers/${slug}` : "/"}
          className="font-semibold text-lg text-foreground hover:text-primary transition-colors"
        >
          {config?.company_name ?? "Careers"}
        </Link>
      </div>
    </header>
  );
}

function CareerFooter() {
  return (
    <footer className="py-6 text-center border-t border-border space-y-2">
      <p className="text-xs text-muted-foreground">
        Powered by{" "}
        <Link
          to="/"
          className="text-primary font-medium hover:text-primary/80 transition-colors"
        >
          Rankora
        </Link>
      </p>
      <p className="text-[10px] text-muted-foreground/50 max-w-md mx-auto">
        By applying, you agree that your information will be processed by the hiring company for recruitment purposes.
      </p>
    </footer>
  );
}

function SocialShareButtons({
  jobId,
  title,
  brandColor,
}: {
  jobId: string;
  title: string;
  brandColor: string;
}) {
  const applyUrl = `${window.location.origin}/apply/${jobId}`;
  const shareText = `${title} — Check out this position`;

  return (
    <TooltipProvider>
      <div className="flex items-center gap-1">
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              onClick={() =>
                window.open(
                  `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(applyUrl)}`,
                  "_blank",
                  "noopener,noreferrer,width=600,height=500"
                )
              }
              className="h-7 w-7 rounded flex items-center justify-center text-muted-foreground/50 hover:text-[#0A66C2] transition-colors"
              aria-label="Share on LinkedIn"
            >
              <Linkedin className="h-3.5 w-3.5" />
            </button>
          </TooltipTrigger>
          <TooltipContent>Share on LinkedIn</TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              onClick={() =>
                window.open(
                  `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(applyUrl)}`,
                  "_blank",
                  "noopener,noreferrer,width=600,height=400"
                )
              }
              className="h-7 w-7 rounded flex items-center justify-center text-muted-foreground/50 hover:text-foreground transition-colors"
              aria-label="Share on X"
            >
              <Twitter className="h-3.5 w-3.5" />
            </button>
          </TooltipTrigger>
          <TooltipContent>Share on X</TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger asChild>
