export default function CareerJobDetail() {
  const { slug, jobId } = useParams<{ slug: string; jobId: string }>();
  const navigate = useNavigate();

  // Fetch job detail (direct query — public, no auth required via is_published check)
  const { data: job, isLoading: jobLoading } = useQuery<JobDetail | null>({
    queryKey: ["career-job", slug, jobId],
    queryFn: async () => {
      if (!jobId) return null;
      const { data, error } = await (supabase as any)
        .from("jobs")
        .select(
          "id, title, job_description, location, department, employment_type, salary_range, created_at, is_published"
        )
        .eq("id", jobId)
        .eq("is_published", true)
        .maybeSingle();
      if (error) throw error;
      return data as JobDetail | null;
    },
    enabled: !!jobId,
    staleTime: 60_000,
  });

  // Fetch career config via existing RPC for branding
  const { data: pageData, isLoading: configLoading } = useQuery({
    queryKey: ["career-page", slug],
    queryFn: async () => {
      if (!slug) return null;
      const { data, error } = await supabase.rpc("get_career_page", {
        p_slug: slug,
      });
      if (error) throw error;
      return data as { config: CareerConfig; jobs: RelatedJob[] } | null;
    },
    enabled: !!slug,
    staleTime: 60_000,
  });

  const config = pageData?.config;
  const brandColor = config?.brand_color ?? "#6366f1";

  // Related jobs — other published jobs from this company (exclude current)
  const relatedJobs = (pageData?.jobs ?? []).filter(
    (j: RelatedJob) => j.id !== jobId
  ).slice(0, 3);

  // Track view on mount
  useEffect(() => {
    if (!jobId) return;
    (supabase as any)
      .rpc("increment_job_view", {
        p_job_id: jobId,
        p_referrer: document.referrer || null,
      })
      .catch(() => {
        // Silently ignore — tracking must never block the page
      });
  }, [jobId]);

  // SEO meta tags + JSON-LD
  useEffect(() => {
    if (!job || !config) return;

    const pageTitle = `${job.title} at ${config.company_name} | Rankora`;
    document.title = pageTitle;

    const setMeta = (nameOrProp: string, content: string) => {
      const isOg = nameOrProp.startsWith("og:");
      const attr = isOg ? "property" : "name";
      let el =
        document.querySelector(`meta[property="${nameOrProp}"]`) ||
        document.querySelector(`meta[name="${nameOrProp}"]`);
      if (!el) {
        el = document.createElement("meta");
        el.setAttribute(attr, nameOrProp);
        document.head.appendChild(el);
      }
      el.setAttribute("content", content);
    };

    const description =
      job.job_description
        ? job.job_description.slice(0, 160).replace(/\n/g, " ").trim()
        : `${job.title} at ${config.company_name}`;

    setMeta("description", description);
    setMeta("og:title", pageTitle);
    setMeta("og:description", description);
    setMeta("og:type", "website");
    setMeta("og:url", window.location.href);
    if (config.logo_url) setMeta("og:image", config.logo_url);

    // Individual JobPosting JSON-LD
    const jsonLd: Record<string, unknown> = {
      "@context": "https://schema.org",
      "@type": "JobPosting",
      title: job.title,
      description: job.job_description ?? job.title,
      datePosted: job.created_at,
      directApply: true,
      hiringOrganization: {
        "@type": "Organization",
        name: config.company_name,
        ...(config.logo_url ? { logo: config.logo_url } : {}),
      },
    };

    if (job.employment_type) {
      jsonLd.employmentType = job.employment_type
        .toUpperCase()
        .replace(/-/g, "_");
    }

    if (job.location) {
      jsonLd.jobLocation = {
        "@type": "Place",
        address: {
          "@type": "PostalAddress",
          addressLocality: job.location,
        },
      };
    }

    if (job.salary_range) {
      jsonLd.baseSalary = {
        "@type": "MonetaryAmount",
        description: job.salary_range,
      };
    }

    const applyUrl = `${window.location.origin}/apply/${job.id}`;
    jsonLd.url = applyUrl;
    jsonLd.applicationContact = {
      "@type": "ContactPoint",
      url: applyUrl,
    };

    let script = document.getElementById(
      "career-job-jsonld"
    ) as HTMLScriptElement | null;
    if (!script) {
      script = document.createElement("script");
      script.id = "career-job-jsonld";
      script.setAttribute("type", "application/ld+json");
      document.head.appendChild(script);
    }
    script.textContent = JSON.stringify(jsonLd);

    return () => {
      document.title = "Rankora";
      document.getElementById("career-job-jsonld")?.remove();
      // Clean up meta tags added by this page
      ["description", "og:title", "og:description", "og:type", "og:url", "og:image"].forEach(
        (key) => {
          document.querySelector(`meta[property="${key}"]`)?.remove();
          document.querySelector(`meta[name="${key}"]`)?.remove();
        }
      );
    };
  }, [job, config]);

  const isLoading = jobLoading || configLoading;

  // ── Loading state ────────────────────────────────────────────────────────
  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <header className="border-b border-border">
          <div className="max-w-5xl mx-auto px-4 py-4 flex items-center gap-3">
            <Skeleton className="h-8 w-8 rounded" />
            <Skeleton className="h-5 w-32" />
          </div>
        </header>
        <main className="flex-1 max-w-5xl mx-auto px-4 py-10 w-full">
          <Skeleton className="h-4 w-48 mb-6" />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="md:col-span-2 space-y-4">
              <Skeleton className="h-8 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
              <div className="space-y-2 mt-6">
                {[1, 2, 3, 4, 5].map((i) => (
                  <Skeleton key={i} className="h-4 w-full" />
                ))}
              </div>
            </div>
            <div className="space-y-4">
              <Skeleton className="h-48 w-full rounded-xl" />
              <Skeleton className="h-10 w-full rounded-md" />
            </div>
          </div>
        </main>
      </div>
    );
  }

  // ── Not found ────────────────────────────────────────────────────────────
  if (!job) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <CareerHeader config={config} slug={slug} />
        <main className="flex-1 flex items-center justify-center px-4 py-16">
          <div className="text-center space-y-4">
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
              <Briefcase className="h-7 w-7 text-muted-foreground" />
            </div>
            <h1 className="text-xl font-semibold">Job not found</h1>
            <p className="text-sm text-muted-foreground">
              This position may have been filled or removed.
            </p>
            {slug && (
              <Link
                to={`/careers/${slug}`}
                className="text-sm font-medium text-primary hover:text-primary/80 transition-colors"
              >
                View all open positions
              </Link>
            )}
          </div>
        </main>
        <CareerFooter />
      </div>
    );
  }

  // ── Metadata items ───────────────────────────────────────────────────────
  const metadataItems = [
    job.location && { icon: MapPin, label: "Location", text: job.location },
    job.department && {
      icon: Building2,
      label: "Department",
      text: job.department,
    },
    job.employment_type && {
      icon: Clock,
      label: "Type",
      text: job.employment_type,
    },
    job.salary_range && {
      icon: DollarSign,
      label: "Salary",
      text: job.salary_range,
    },
    {
      icon: Calendar,
      label: "Posted",
      text: formatDistanceToNow(new Date(job.created_at), { addSuffix: true }),
    },
  ].filter(Boolean) as { icon: typeof MapPin; label: string; text: string }[];

  // ── Main render ──────────────────────────────────────────────────────────
  return (
    <div className="min-h-screen bg-background flex flex-col">
      <CareerHeader config={config} slug={slug} />

      <main className="flex-1 max-w-5xl mx-auto px-4 py-10 w-full">
        {/* Breadcrumb */}
        <nav className="flex items-center gap-1.5 text-xs text-muted-foreground mb-6" aria-label="Breadcrumb">
          {slug && (
            <>
              <Link
                to={`/careers/${slug}`}
                className="hover:text-foreground transition-colors"
              >
                {config?.company_name ?? "Careers"}
              </Link>
              <span>/</span>
            </>
          )}
          <span className="text-foreground font-medium truncate max-w-[200px]">
            {job.title}
          </span>
        </nav>

        {/* Back link */}
        {slug && (
          <Link
            to={`/careers/${slug}`}
            className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-6 group"
          >
            <ArrowLeft className="h-4 w-4 group-hover:-translate-x-0.5 transition-transform duration-150" />
            All open positions
          </Link>
        )}

        {/* Two-column layout */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-start">
          {/* LEFT — Job description (2/3) */}
          <div className="md:col-span-2 space-y-6">
            {/* Title + sharing */}
            <div className="space-y-2">
              <h1 className="text-2xl font-bold text-foreground leading-tight">
                {job.title}
              </h1>
              {config?.company_name && (
                <p className="text-base text-muted-foreground">
                  {config.company_name}
                </p>
              )}
              {/* Inline metadata pills on mobile */}
              <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1 md:hidden">
                {metadataItems.map((m, i) => (
                  <span
                    key={i}
                    className="flex items-center gap-1 text-sm text-muted-foreground"
                  >
                    <m.icon className="h-3.5 w-3.5 shrink-0" />
                    {m.text}
                  </span>
                ))}
              </div>
              {/* Social share */}
              <div className="flex items-center gap-2 pt-1">
                <span className="text-xs text-muted-foreground">Share:</span>
                <SocialShareButtons
                  jobId={job.id}
                  title={job.title}
                  brandColor={brandColor}
                />
              </div>
            </div>

            {/* Job description body */}
            {job.job_description ? (
              <div className="prose prose-sm max-w-none text-foreground leading-relaxed">
                {job.job_description.split("\n").map((line, i) =>
                  line.trim() ? (
                    <p key={i} className="mb-3 text-sm">
                      {line}
                    </p>
                  ) : (
                    <br key={i} />
                  )
                )}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground italic">
                No job description provided.
              </p>
            )}

            {/* Apply CTA (bottom of description on mobile) */}
            <div className="md:hidden">
              <Button
                className="w-full text-white font-semibold"
                style={{ backgroundColor: brandColor }}
                onClick={() => navigate(`/apply/${job.id}`)}
              >
                Apply Now
              </Button>
            </div>
          </div>

          {/* RIGHT — Metadata card + Apply button (1/3) */}
          <div className="space-y-4 hidden md:block">
            {/* Job info card */}
            <div
              className="rounded-xl border border-border bg-card p-5 space-y-4"
            >
              {metadataItems.map((m, i) => (
                <div key={i} className="flex items-start gap-3">
                  <div className="mt-0.5 rounded-md bg-muted p-1.5 shrink-0">
                    <m.icon className="h-3.5 w-3.5 text-muted-foreground" />
                  </div>
                  <div>
                    <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider">
                      {m.label}
                    </p>
                    <p className="text-sm font-medium text-foreground mt-0.5">
                      {m.text}
                    </p>
                  </div>
                </div>
              ))}
            </div>

            {/* Apply button */}
            <Button
              className="w-full text-white font-semibold"
              style={{ backgroundColor: brandColor }}
              onClick={() => navigate(`/apply/${job.id}`)}
            >
              Apply Now
            </Button>

            {/* Share */}
            <div className="flex items-center justify-center gap-2">
              <span className="text-xs text-muted-foreground">Share this job:</span>
              <SocialShareButtons
                jobId={job.id}
                title={job.title}
                brandColor={brandColor}
              />
            </div>
          </div>
        </div>

        {/* Related jobs section */}
        {relatedJobs.length > 0 && (
          <div className="mt-12 pt-8 border-t border-border">
            <h2 className="text-base font-semibold text-foreground mb-4">
              More open positions
            </h2>
            <div className="grid gap-3">
              {relatedJobs.map((rj) => (
                <Link
                  key={rj.id}
                  to={`/careers/${slug}/jobs/${rj.id}`}
                  className="group flex items-center justify-between rounded-xl border border-border bg-card px-5 py-4 hover:shadow-sm transition-all duration-150"
                >
                  <div className="space-y-1 min-w-0">
                    <p className="text-sm font-semibold text-foreground group-hover:text-primary transition-colors truncate">
                      {rj.title}
                    </p>
                    <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5">
                      {rj.location && (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <MapPin className="h-3 w-3" />
                          {rj.location}
                        </span>
                      )}
                      {rj.department && (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <Building2 className="h-3 w-3" />
                          {rj.department}
                        </span>
                      )}
                      {rj.employment_type && (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock className="h-3 w-3" />
                          {rj.employment_type}
                        </span>
                      )}
                    </div>
                  </div>
                  <Badge
                    variant="secondary"
                    className="shrink-0 ml-4 text-[11px]"
                  >
                    View
                  </Badge>
                </Link>
              ))}
            </div>
          </div>
        )}
      </main>

      <CareerFooter />
    </div>
  );
}

